{
  "id": "R1",
  "summary_ko": "염화나트륨 조각이 떠서 회전하는 방식이 비현실적임.",
  "claims": [
    {
      "id": "R1.S1",
      "evidence": "The way the piece of sodium chloride floats and rotates is unrealistic.",
      "symptom_ko": "염화나트륨 조각이 떠서 회전하는 방식이 비현실적임",
      "is_anomaly": true,
      "specificity": "broad",
      "target_evidence": "the piece of sodium chloride",
      "explicit_detail_evidence": [],
      "missing_details_ko": "회전 및 부유 움직임이 구체적으로 어떤 궤적, 속도, 방향 또는 물리적 결함을 보여 비현실적인지 명시되지 않음"
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "불타는 물체가 영상 전체 시간 동안 떠다니며 회전한다.",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "The burning object floats and rotates for the whole duration of the clip.",
      "symptom_ko": "불타는 물체가 영상 내내 공중에 떠서 회전함",
      "is_anomaly": false,
      "specificity": "neutral",
      "target_evidence": "The burning object",
      "explicit_detail_evidence": [],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "오른쪽에서 불꽃이 무작위로 날아다님.",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "Sparks fly around randomly on the right side.",
      "symptom_ko": "오른쪽에서 불꽃이 무작위로 날아다님",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Sparks",
      "explicit_detail_evidence": [
        "fly around randomly",
        "on the right side"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "target_relation": "different",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "The burning object floats and rotates for the whole duration of the clip.",
      "candidate_evidence": "Sparks and embers freeze, drift erratically, or flicker without natural ballistic motion.",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 불타는 물체 본체의 부유 및 회전 동작을 설명하는 반면, 후보 C1은 불꽃과 잔해(sparks and embers)의 불자연스러운 움직임 결함을 다루고 있어 서로 다른 대상에 관한 명확한 분리가 성립합니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "target_relation": "different",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "The burning object floats and rotates for the whole duration of the clip.",
      "candidate_evidence": "Flame wrapping the mineral exhibits unnatural morphing and static sections despite simulated turbulent airflow.",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 물체 자체의 지속적인 부유 및 회전을 기술하는 반면, 후보 C2는 광물을 감싸는 불길(Flame)의 부자연스러운 변형 및 정적 구간 결함을 지적하므로 명시적으로 서로 다른 현상 및 대상에 대한 설명입니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "target_relation": "different",
      "reference_claim_ids": [
        "R2.S1"
      ],
      "reference_evidence": "The burning object floats and rotates for the whole duration of the clip.",
      "candidate_evidence": "Right portion of the mineral crystal gradually becomes more transparent and smooths out internal fracture structures.",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 불타는 물체의 전체적인 회전 및 부유 움직임을 나타내는 반면, 후보 C3은 광물 결정 우측 부위의 투명화 및 내부 균열 구조 소실이라는 구체적인 텍스처/구조 결함을 다루고 있어 서로 다른 결함/현상으로 명확히 구분됩니다."
    }
  ]
}

